(() => {
'use strict';
const KEY='siren-system-v2';
const pillars={Glow:{icon:'✿',color:'#f5e5eb',desc:'Beauty & body care'},Power:{icon:'☼',color:'#f9ebdf',desc:'Strength & nourishment'},Grace:{icon:'❀',color:'#f8ecdf',desc:'Presence & elegance'},Wisdom:{icon:'✧',color:'#eee8f5',desc:'Curiosity & growth'},Devotion:{icon:'♡',color:'#e8f0e8',desc:'Stillness & spirit'}};
const baseQuests=[
{id:'glow1',pillar:'Glow',name:'Glycolic acid + moisturising routine',sub:'Care for your skin gently',xp:10},
{id:'glow2',pillar:'Glow',name:'Dry brushing + body oil',sub:'A soft body-care ritual',xp:10},
{id:'glow3',pillar:'Glow',name:'Hair, sun & getting-ready care',sub:'Show up for your body with kindness',xp:20},
{id:'power1',pillar:'Power',name:'Strength or joyful movement',sub:'Choose movement that feels good',xp:30},
{id:'power2',pillar:'Power',name:'Nourishing, balanced meals',sub:'Meet your nourishment intention',xp:20,original:true},
{id:'power3',pillar:'Power',name:'Hydrate, stretch or rest',sub:'Listen to what your body needs',xp:15},
{id:'grace1',pillar:'Grace',name:'Practise posture & grace',sub:'Move through the day with presence',xp:15,original:true},
{id:'grace2',pillar:'Grace',name:'A mindful pause between things',sub:'One breath, one moment at a time',xp:10},
{id:'grace3',pillar:'Grace',name:'Get ready with intention',sub:'Add one detail that delights you',xp:10},
{id:'wisdom1',pillar:'Wisdom',name:'Read something that feeds you',sub:'A few pages count',xp:25},
{id:'wisdom2',pillar:'Wisdom',name:'Write to your future self',sub:'Name the woman you are becoming',xp:10,original:true},
{id:'wisdom3',pillar:'Wisdom',name:'Learn or make something',sub:'Let curiosity have a little room',xp:20},
{id:'devotion1',pillar:'Devotion',name:'Complete your Holy Hour',sub:'A protected hour for your own becoming',xp:15,original:true},
{id:'devotion2',pillar:'Devotion',name:'Set a morning intention',sub:'What would make today feel like yours?',xp:10},
{id:'devotion3',pillar:'Devotion',name:'Find a moment of gratitude',sub:'Notice a small thing that held you',xp:15}
];
const levels=[['Pearl Dreamer','The First Spark',0,500],['Blush Beginner','The Gentle Bloom',500,1200],['Rose Ritualist','The Ritual Keeper',1200,2400],['Siren in Bloom','The Inner Light',2400,4000],['Moonlit Muse','The Becoming',4000,6500],['Velvet Visionary','The Radiant One',6500,9500],['The Siren','Fully Becoming',9500,Infinity]];
const challenge=["Write one kind sentence to yourself.","Take a slow walk and notice the light.","Create a tiny morning ritual.","Read a page just for pleasure.","Choose a nourishing meal you enjoy.","Stretch in a way that feels lovely.","Write a note to future you.","Make a playlist for your becoming.","Take a screen-free moment outside.","Wear something that feels like you.","Practise your soft, steady posture.","Rest without needing to earn it.","Learn one small new thing.","Do your favourite body-care ritual.","Name one boundary that protects your peace.","Notice something your body did for you.","Enjoy a Holy Hour, at your own pace.","Make a space around you feel beautiful.","Tell yourself what you are proud of.","Choose joy in one ordinary moment.","Write your own Siren promise for tomorrow."];
const morning=[['Wake softly','Open the curtains and let in the day.'],['Water & nourishment','Have a drink and choose a satisfying breakfast.'],['Face & body care','Cleanse, moisturise, and use SPF if it is daytime.'],['Move a little','Stretch, take a walk, or follow your energy.'],['Set an intention','Write one sentence about how you want to feel.'],['Get dressed with care','Choose comfort and one detail you love.']];
const evening=[['Let the day settle','Lower the lights and set your phone aside.'],['Gentle cleanse','Remove the day and moisturise your skin.'],['Body-care moment','Body oil, a warm shower, or a soft stretch.'],['Prepare with kindness','Set out one small thing for tomorrow.'],['Future-self note','Write one thing you did well today.'],['Rest & release','Choose a calming wind-down and let rest count.']];
const holy=[['Arrive','Make tea, light a candle, or sit somewhere peaceful.'],['Tend to your body','Choose nourishing food, care, or restorative movement.'],['Feed your mind','Read, learn, journal, or make something.'],['Reconnect','Step outside, notice beauty, or sit in stillness.'],['Set a loving direction','Name one thing you are becoming proud of.']];
const fitness=[['MON','✿','Strength or rest'],['TUE','☼','Walk & mobility'],['WED','♡','Strength or joy'],['THU','☾','Gentle recovery'],['FRI','✧','Strength or walk'],['SAT','❀','Something playful'],['SUN','☁','Rest & reset']];
const rewardDefaults=[{id:'bath',emoji:'🛁',name:'Glow bath',desc:'A long, lovely soak with your favourite scents.',cost:8},{id:'playlist',emoji:'🎧',name:'Playlist treat',desc:'Make a soundtrack for this chapter of you.',cost:5},{id:'mirror',emoji:'🪞',name:'Mirror ritual',desc:'A few minutes of affirmations and self-admiration.',cost:6},{id:'double',emoji:'✨',name:'Double-XP day',desc:'A playful 2× quest XP celebration day.',cost:18},{id:'flowers',emoji:'🌷',name:'Fresh flowers',desc:'Bring a little seasonal beauty home.',cost:16},{id:'slow',emoji:'☕',name:'Slow morning',desc:'Protect an unhurried hour just for you.',cost:12},{id:'book',emoji:'📚',name:'A new chapter',desc:'Choose a little bookish treat for your shelf.',cost:20},{id:'custom',emoji:'🎀',name:'Your own little treat',desc:'Choose something personal that feels special.',cost:10}];
let data=load(), currentRoutine='morning',reviewPeriod='weekly', activeMood='';
function blank(){return {version:2,name:'Zai',logs:{},totalBonus:0,bonusEvents:[],spentPearls:0,rewards:rewardDefaults,redeemed:[],customQuests:[],challengeStart:null,challengeDone:[],routineChecks:{},journal:{},reviews:{},settings:{streak:true}}}
function load(){try{let d=JSON.parse(localStorage.getItem(KEY));return d&&d.version===2?{...blank(),...d}:blank()}catch{return blank()}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(data))}catch{toast('Your browser storage is full. Export a copy of your diary.')}}
const pad=n=>String(n).padStart(2,'0');const iso=(d=new Date())=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;const today=iso();
const parseDate=s=>new Date(`${s}T12:00:00`);const pretty=s=>parseDate(s).toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'});const weekStart=(d=new Date())=>{let x=new Date(d);x.setHours(12,0,0,0);x.setDate(x.getDate()-((x.getDay()+6)%7));return iso(x)};const monthStart=(d=new Date())=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-01`;
function log(day=today){return data.logs[day]||(data.logs[day]={done:[]})}
function allQuests(){return [...baseQuests,...data.customQuests.map(q=>({...q,sub:'A little ritual, chosen by you'}))]}
function questPoints(day=today){const done=(data.logs[day]?.done||[]);return allQuests().filter(q=>done.includes(q.id)).reduce((n,q)=>n+q.xp,0)}
function totalQuestXP(){return Object.keys(data.logs).reduce((s,d)=>s+questPoints(d),0)}
function availablePearls(){return Math.max(0,Math.floor(totalQuestXP()/25)-data.spentPearls)}
function dailyBonus(day=today){return data.bonusEvents.filter(e=>e.date===day).reduce((s,e)=>s+e.xp,0)}
function totalXP(){return totalQuestXP()+data.totalBonus}
function activeDays(){return Object.keys(data.logs).filter(d=>(data.logs[d]?.done||[]).length>0).sort()}
function streak(){if(!data.settings.streak)return 0;let days=new Set(activeDays()),cur=new Date();if(!days.has(iso(cur))){cur.setDate(cur.getDate()-1);if(!days.has(iso(cur)))return 0}let n=0;while(days.has(iso(cur))){n++;cur.setDate(cur.getDate()-1)}return n}
function weekXP(){let start=weekStart();return Object.keys(data.logs).filter(d=>d>=start&&d<=today).reduce((s,d)=>s+questPoints(d)+dailyBonus(d),0)}
function levelInfo(){let xp=totalXP();let i=levels.findIndex(l=>xp<l[3]);if(i<0)i=levels.length-1;let l=levels[i],progress=l[3]===Infinity?100:Math.min(100,((xp-l[2])/(l[3]-l[2]))*100);return {i,l,xp,progress,next:l[3]}}
function activeStreakFor(date){let days=new Set(activeDays());let cur=parseDate(date),n=0;while(days.has(iso(cur))){n++;cur.setDate(cur.getDate()-1)}return n}
function maybeAward(day){let d=log(day);let base=baseQuests.length;let complete=baseQuests.every(q=>d.done.includes(q.id));if(complete&&!data.bonusEvents.some(e=>e.id==='perfect:'+day)){data.bonusEvents.push({id:'perfect:'+day,date:day,xp:50,label:'Perfect Glow Day'});data.totalBonus+=50;toast('Perfect Glow Day! +50 bonus XP ✨')}
let s=activeStreakFor(day);if(s>0&&s%7===0){let id='streak:'+day;if(!data.bonusEvents.some(e=>e.id===id)){data.bonusEvents.push({id,date:day,xp:100,label:`${s}-day streak`});data.totalBonus+=100;toast(`${s} days of showing up! +100 XP ♡`)}}
}
function toggleQuest(id){let d=log();let at=d.done.indexOf(id);if(at>=0)d.done.splice(at,1);else d.done.push(id);maybeAward(today);save();render();}
function nav(page){if(page==='rewards')page='rewards';document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+page));document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));let label={home:'MY SANCTUARY · YOUR TODAY',quests:'YOUR SANCTUARY · DAILY QUESTS',rituals:'YOUR SANCTUARY · RITUALS',journey:'YOUR SANCTUARY · SELF-ENCHANTMENT',journal:'YOUR SANCTUARY · REFLECTIONS',reviews:'YOUR SANCTUARY · REVIEWS',settings:'YOUR SANCTUARY · SETTINGS',rewards:'YOUR SANCTUARY · PEARL SHOP'};document.getElementById('crumb').textContent=label[page]||'YOUR SANCTUARY';document.getElementById('sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'})}
function toast(msg){let el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2600)}
function renderHome(){let g=new Date().getHours();document.getElementById('greeting').textContent=(g<12?'Good morning':g<18?'Good afternoon':'Good evening')+', '+(data.name||'lovely')+'.';let li=levelInfo();document.getElementById('levelName').textContent=li.l[0];document.getElementById('levelSub').textContent=`Level ${li.i+1} · ${li.l[1]}`;document.getElementById('levelPct').textContent=Math.round(li.progress)+'%';document.getElementById('levelBar').style.width=li.progress+'%';document.getElementById('levelHint').textContent=li.next===Infinity?`${li.xp.toLocaleString()} XP · final form, lovely`: `${Math.max(0,li.next-li.xp)} XP to your next level`;
let st=streak();document.getElementById('streakCount').textContent=st;document.getElementById('streakHint').textContent=st?`${st} ${st===1?'day':'days'} of gentle showing up.`:'Start a ritual today, lovely.';
let ws=weekStart(),monday=parseDate(ws);document.getElementById('weekDots').innerHTML=Array.from({length:7},(_,i)=>{let d=new Date(monday);d.setDate(d.getDate()+i);let key=iso(d);return `<span class="${activeDays().includes(key)?'done':''}">${['M','T','W','T','F','S','S'][i]}</span>`}).join('');document.getElementById('weekXP').textContent=weekXP();document.getElementById('topDate').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});
let done=log().done.length, xp=questPoints()+dailyBonus();document.getElementById('todayProgress').textContent=`${done} of 15`;document.getElementById('todayXp').textContent=`${xp} XP gathered today`;document.getElementById('questNavCount').textContent=`${done}/15`;document.getElementById('pearlCount').textContent=availablePearls();document.getElementById('pillarProgress').innerHTML=Object.entries(pillars).map(([p,v])=>{let qs=baseQuests.filter(q=>q.pillar===p),n=qs.filter(q=>log().done.includes(q.id)).length;return `<div class="pillar-item"><div class="pillar-bubble" style="background:${v.color}">${v.icon}</div><strong>${p}</strong><small>${n}/${qs.length} quests</small></div>`}).join('');let quotes=['You do not have to bloom all at once.','Your softness is a strength you can return to.','You are allowed to begin again, gently.','Little promises make a life feel like yours.','Rest is part of your becoming.'];document.getElementById('dailyQuote').textContent=quotes[(new Date().getDate()+quoteOffset)%quotes.length];document.getElementById('homeRewards').innerHTML=data.rewards.slice(0,4).map(r=>`<div class="reward-chip" data-goto="rewards"><span class="reward-emoji">${r.emoji}</span><span><b>${esc(r.name)}</b><small>✧ ${r.cost} pearls</small></span></div>`).join('');}
let quoteOffset=0;
function renderQuests(){let groups=document.getElementById('questGroups'),all=allQuests(),done=log().done;groups.innerHTML=Object.entries(pillars).map(([p,v])=>{let qs=all.filter(q=>q.pillar===p),points=qs.filter(q=>done.includes(q.id)).reduce((s,q)=>s+q.xp,0);return `<article class="panel quest-group"><div class="quest-group-head"><span class="pillar-icon" style="background:${v.color}">${v.icon}</span><div><h3>${p}</h3><small>${v.desc}</small></div><span class="group-xp">${points} XP</span></div>${qs.map(q=>`<div class="quest-row ${done.includes(q.id)?'done':''}" role="checkbox" aria-checked="${done.includes(q.id)}" tabindex="0" data-quest="${q.id}"><span class="checkmark">✓</span><span class="quest-title">${esc(q.name)}<small class="quest-sub">${esc(q.sub||'A gentle ritual')}</small></span><span class="quest-points">+${q.xp} XP</span></div>`).join('')}</article>`}).join('');let xp=questPoints(),base=baseQuests.reduce((s,q)=>s+q.xp,0);document.getElementById('questXp').textContent=xp;document.getElementById('questBar').style.width=Math.min(100,xp/base*100)+'%';document.getElementById('questHint').textContent=done.length===15?'Every pillar has bloomed today.':done.length?`${done.length} little promise${done.length===1?'':'s'} kept.`:'A gentle beginning is still a beginning.';document.getElementById('perfectBadge').classList.toggle('unlocked',baseQuests.every(q=>done.includes(q.id)));document.getElementById('customQuestList').innerHTML=data.customQuests.length?data.customQuests.map(q=>`<div class="custom-quest-row"><b>${esc(q.name)} <span>${q.pillar} · +${q.xp} XP</span></b><button class="text-btn" data-remove-quest="${q.id}">Remove</button></div>`).join(''):'<div class="gentle-note">No personal quests yet. Add a small ritual that feels like you.</div>';}
function renderRituals(){let set={morning,evening,holy}[currentRoutine],names={morning:['MORNING RITUAL','Wake into your own rhythm','No perfect mornings required. Keep the steps that support you, and leave the rest.'],evening:['EVENING RITUAL','Let the day soften','A few kind closing rituals can help you feel held at the end of the day.'],holy:['YOUR HOLY HOUR','One hour, belonging to you','The Holy Hour was a protected space in your original handbook. Shape it to your energy and your season.']},[eyebrow,title,desc]=names[currentRoutine],key=today+':'+currentRoutine,checks=data.routineChecks[key]||[];document.getElementById('routineContent').innerHTML=`<article class="panel routine-card"><span class="eyebrow">${eyebrow}</span><h2>${title}</h2><p>${desc}</p><div class="routine-list">${set.map(([n,d],i)=>`<div class="routine-step ${checks.includes(i)?'done':''}"><button data-step="${i}">${checks.includes(i)?'✓':'○'}</button><span>${n}<small>${d}</small></span></div>`).join('')}</div><div class="routine-footer"><span>${checks.length} of ${set.length} little moments · no XP, just care</span><button class="text-btn" id="resetRoutine">Reset this ritual</button></div></article>`;document.getElementById('fitnessGrid').innerHTML=fitness.map(d=>`<div class="fitness-day"><b>${d[0]}</b><span>${d[1]}</span><small>${d[2]}</small></div>`).join('')}
function renderJourney(){let started=!!data.challengeStart,done=new Set(data.challengeDone),count=done.size;document.getElementById('challengeTitle').textContent=started?`Day ${Math.min(21,count+1)} of your becoming`:'Begin whenever you are ready';document.getElementById('challengeSub').textContent=started?`Started ${pretty(data.challengeStart)} · your pace is the right pace.`:'A day counts when you choose to show up for yourself.';document.getElementById('challengeCount').textContent=`${count} / 21 days`;document.getElementById('challengeBar').style.width=(count/21*100)+'%';document.getElementById('challengeStart').textContent=started?'Continue my journey →':'Begin my journey →';document.getElementById('challengeGrid').innerHTML=challenge.map((p,i)=>`<button class="challenge-day ${done.has(i)?'done':''}" data-challenge="${i}"><span class="tiny-check">${done.has(i)?'✓':'+'}</span><b>Day ${i+1}</b><p>${p}</p></button>`).join('');let ach=[['✿','First bloom','Complete your first quest',totalQuestXP()>0],['☼','Seven sunrises','Reach a seven-day streak',streak()>=7],['♡','Pearl keeper','Gather your first 10 pearls',availablePearls()>=10],['✧','Perfectly you','Complete a Perfect Glow Day',data.bonusEvents.some(e=>e.label==='Perfect Glow Day')],['☾','Holy Hour','Complete your Holy Hour routine',Object.keys(data.routineChecks).some(k=>k.endsWith(':holy')&&(data.routineChecks[k]||[]).length===holy.length)],['🌷','21 gentle days','Complete the Self-Enchantment journey',count>=21],['📖','Words to keep','Save a reflection',Object.keys(data.journal).length>0],['✨','A new level','Reach Siren in Bloom',levelInfo().i>=3]];document.getElementById('achievements').innerHTML=ach.map(a=>`<div class="achievement ${a[3]?'unlocked':''}"><span>${a[0]}</span><div><b>${a[1]}</b><small>${a[3]?'Gathered with care':a[2]}</small></div></div>`).join('')}
function renderJournal(){let j=data.journal[today]||{};document.getElementById('journalDate').textContent=pretty(today);document.getElementById('journalText').value=j.text||'';activeMood=j.mood||'';document.querySelectorAll('.mood-select button').forEach(b=>b.classList.toggle('selected',b.dataset.mood===activeMood));let entries=Object.entries(data.journal).sort((a,b)=>b[0].localeCompare(a[0])).slice(0,8);document.getElementById('journalEntries').innerHTML=entries.length?entries.map(([d,e])=>`<div class="journal-entry"><b>${e.mood?esc(e.mood)+' day':'A page to keep'}</b><small>${pretty(d)}</small><p>${esc(e.text||'A quiet check-in.')}</p></div>`).join(''):'<p class="gentle-note">Your first page is waiting whenever you are ready.</p>'}
function periodStart(){return reviewPeriod==='weekly'?weekStart():monthStart()}
function reviewData(){let start=periodStart(),dates=Object.keys(data.logs).filter(d=>d>=start&&d<=today),days=dates.filter(d=>(data.logs[d]?.done||[]).length>0),xp=dates.reduce((s,d)=>s+questPoints(d)+dailyBonus(d),0),q=days.reduce((s,d)=>s+(data.logs[d]?.done||[]).length,0);return {start,days,xp,q}}
function renderReviews(){let {start,days,xp,q}=reviewData(),period=reviewPeriod;document.getElementById('reviewTitle').textContent=period==='weekly'?'Your weekly reflection':'Your monthly reflection';let obj=data.reviews[period+':'+start]||{};document.getElementById('reviewEasy').value=obj.easy||'';document.getElementById('reviewRoom').value=obj.room||'';document.getElementById('reviewProud').value=obj.proud||'';document.getElementById('reviewStats').innerHTML=`<div class="review-stat"><b>${days.length}</b><small>days you showed up</small></div><div class="review-stat"><b>${xp}</b><small>XP gathered with care</small></div><div class="review-stat"><b>${q}</b><small>little promises kept</small></div>`;document.getElementById('reviewPillars').innerHTML=Object.entries(pillars).map(([p,v])=>{let total=days.reduce((s,d)=>s+baseQuests.filter(a=>a.pillar===p&&data.logs[d].done.includes(a.id)).length,0);let max=days.length*3||1;return `<div class="pillar-review"><span>${v.icon} ${p}</span><div class="progress-track"><span style="width:${Math.min(100,total/max*100)}%;background:${v.color.replace(')',')')}"></span></div><small>${total} quests</small></div>`}).join('');document.getElementById('reviewFitness').innerHTML=fitness.map(d=>`<div class="fitness-day"><b>${d[0]}</b><span>${d[1]}</span><small>${d[2]}</small></div>`).join('')}
function renderShop(){document.getElementById('shopPearls').textContent=availablePearls();document.getElementById('shopGrid').innerHTML=data.rewards.map(r=>`<article class="shop-item"><div class="shop-item-emoji">${r.emoji}</div><h3>${esc(r.name)}</h3><p>${esc(r.desc)}</p><div class="shop-item-foot"><b>✧ ${r.cost} pearls</b><button class="secondary-btn" data-buy="${r.id}">Choose this</button></div></article>`).join('');document.getElementById('redeemedList').innerHTML=data.redeemed.length?data.redeemed.slice().reverse().map(r=>`<div class="redeemed-row">${r.emoji} <b>${esc(r.name)}</b><small>${pretty(r.date)} · ${r.cost} pearls</small></div>`).join(''):'<div class="gentle-note">Your treat memories will live here.</div>'}
function renderSettings(){document.getElementById('nameInput').value=data.name||'';document.getElementById('startDay').value=data.challengeStart||'';document.getElementById('streakToggle').checked=data.settings.streak!==false;document.getElementById('pillarLegend').innerHTML=Object.entries(pillars).map(([p,v])=>`<div class="legend-item"><span class="pillar-icon" style="background:${v.color}">${v.icon}</span><b>${p}</b><small>${v.desc}</small></div>`).join('')}
function render(){renderHome();renderQuests();renderRituals();renderJourney();renderJournal();renderReviews();renderShop();renderSettings()}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function modal(title,body,submit){document.getElementById('modalBody').innerHTML=`<h2>${title}</h2>${body}<div class="modal-actions"><button class="secondary-btn" id="modalCancel">Cancel</button><button class="primary-btn small-btn" id="modalSubmit">Add to my sanctuary</button></div>`;document.getElementById('modalBackdrop').classList.add('show');document.getElementById('modalCancel').onclick=closeModal;document.getElementById('modalSubmit').onclick=()=>{if(submit())closeModal()};setTimeout(()=>document.querySelector('#modal input')?.focus(),50)}
function closeModal(){document.getElementById('modalBackdrop').classList.remove('show')}
function addQuestModal(){modal('A little ritual, chosen by you','<label>Quest name</label><input id="newQuestName" maxlength="60" placeholder="A small thing that feels like care"><label>Which pillar?</label><select id="newQuestPillar">'+Object.keys(pillars).map(p=>`<option>${p}</option>`).join('')+'</select><label>XP (5–25)</label><input id="newQuestXP" type="number" min="5" max="25" value="10">',()=>{let name=document.getElementById('newQuestName').value.trim(),xp=Math.max(5,Math.min(25,Number(document.getElementById('newQuestXP').value)||10));if(!name){toast('Give your little quest a name first ♡');return false}data.customQuests.push({id:'custom-'+Date.now(),name,pillar:document.getElementById('newQuestPillar').value,xp});save();render();toast('Your personal quest is ready ✿');return true})}
function addRewardModal(){modal('Add a little treat','<label>What would feel lovely?</label><input id="newRewardName" maxlength="40" placeholder="A treat for your future self"><label>Emoji</label><input id="newRewardEmoji" maxlength="4" value="🎀"><label>Pearl cost (1–100)</label><input id="newRewardCost" type="number" min="1" max="100" value="10"><label>A note about it</label><input id="newRewardDesc" maxlength="100" placeholder="Make it special to you">',()=>{let name=document.getElementById('newRewardName').value.trim();if(!name){toast('Name your little treat first ♡');return false}data.rewards.push({id:'reward-'+Date.now(),name,emoji:document.getElementById('newRewardEmoji').value||'🎀',cost:Math.max(1,Math.min(100,Number(document.getElementById('newRewardCost').value)||10)),desc:document.getElementById('newRewardDesc').value||'A little treat chosen by you.'});save();render();return true})}
function buy(id){let r=data.rewards.find(x=>x.id===id);if(!r)return;if(availablePearls()<r.cost){toast(`You need ${r.cost-availablePearls()} more pearls for this treat ♡`);return}data.spentPearls+=r.cost;data.redeemed.push({name:r.name,emoji:r.emoji,cost:r.cost,date:today});save();render();toast(`${r.name} is yours to enjoy ✨`)}
function saveCopy(){let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`siren-diary-${today}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('A copy of your diary is ready ↗')}
// Navigation & actions
for(const b of document.querySelectorAll('[data-page]'))b.addEventListener('click',()=>nav(b.dataset.page));for(const b of document.querySelectorAll('[data-goto]'))b.addEventListener('click',()=>nav(b.dataset.goto));
document.getElementById('menuBtn').onclick=()=>document.getElementById('sidebar').classList.toggle('open');document.getElementById('newQuote').onclick=()=>{quoteOffset++;renderHome()};document.getElementById('exportBtn').onclick=saveCopy;document.getElementById('exportSettings').onclick=saveCopy;document.getElementById('addQuestBtn').onclick=addQuestModal;document.getElementById('addRewardBtn').onclick=addRewardModal;
document.getElementById('questGroups').addEventListener('click',e=>{let row=e.target.closest('[data-quest]');if(row)toggleQuest(row.dataset.quest)});document.getElementById('questGroups').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){let row=e.target.closest('[data-quest]');if(row){e.preventDefault();toggleQuest(row.dataset.quest)}}});document.getElementById('customQuestList').addEventListener('click',e=>{let b=e.target.closest('[data-remove-quest]');if(b){let id=b.dataset.removeQuest;data.customQuests=data.customQuests.filter(q=>q.id!==id);for(let d of Object.values(data.logs))d.done=d.done.filter(x=>x!==id);save();render();toast('Personal quest removed.')}});
document.querySelector('.routine-tabs').addEventListener('click',e=>{let b=e.target.closest('[data-routine]');if(!b)return;currentRoutine=b.dataset.routine;document.querySelectorAll('.routine-tabs .tab-btn').forEach(x=>x.classList.toggle('active',x===b));renderRituals()});document.getElementById('routineContent').addEventListener('click',e=>{let step=e.target.closest('[data-step]');if(step){let key=today+':'+currentRoutine,arr=data.routineChecks[key]||[],i=Number(step.dataset.step);data.routineChecks[key]=arr.includes(i)?arr.filter(x=>x!==i):[...arr,i];save();renderRituals()}if(e.target.id==='resetRoutine'){delete data.routineChecks[today+':'+currentRoutine];save();renderRituals()}});
document.getElementById('challengeStart').onclick=()=>{if(!data.challengeStart){data.challengeStart=today;save();toast('Your first gentle day begins now ♡')}nav('journey');renderJourney()};document.getElementById('challengeGrid').addEventListener('click',e=>{let b=e.target.closest('[data-challenge]');if(!b)return;if(!data.challengeStart){data.challengeStart=today}let n=Number(b.dataset.challenge);data.challengeDone=data.challengeDone.includes(n)?data.challengeDone.filter(x=>x!==n):[...data.challengeDone,n];save();render();toast(data.challengeDone.includes(n)?`Day ${n+1} gathered with care ✿`:`Day ${n+1} reopened for your pace ♡`) });
document.getElementById('moodSelect').onclick=e=>{let b=e.target.closest('[data-mood]');if(b){activeMood=b.dataset.mood;document.querySelectorAll('.mood-select button').forEach(x=>x.classList.toggle('selected',x===b))}};
const prompts=['What felt like care today?','What made you feel most like yourself?','What small promise did you keep?','What are you ready to release?','What did your body do for you today?','What would future-you thank you for?'];let promptOffset=0;document.getElementById('newPrompt').onclick=()=>{promptOffset++;document.getElementById('journalPrompt').textContent='A gentle prompt: '+prompts[(new Date().getDate()+promptOffset)%prompts.length]};document.getElementById('journalPrompt').textContent='A gentle prompt: '+prompts[new Date().getDate()%prompts.length];document.getElementById('saveJournal').onclick=()=>{let text=document.getElementById('journalText').value.trim();if(!text&&!activeMood){toast('Add a few words or choose how you are arriving ♡');return}data.journal[today]={text,mood:activeMood,updated:new Date().toISOString()};save();renderJournal();document.getElementById('savedMsg').textContent='Saved with care ♡';setTimeout(()=>document.getElementById('savedMsg').textContent='',2600)};
document.querySelector('.review-tabs').onclick=e=>{let b=e.target.closest('[data-review]');if(!b)return;reviewPeriod=b.dataset.review;document.querySelectorAll('.review-tabs .tab-btn').forEach(x=>x.classList.toggle('active',x===b));renderReviews()};document.getElementById('saveReview').onclick=()=>{let {start}=reviewData();data.reviews[reviewPeriod+':'+start]={easy:document.getElementById('reviewEasy').value,room:document.getElementById('reviewRoom').value,proud:document.getElementById('reviewProud').value};save();document.getElementById('reviewSaved').textContent='Reflection tucked away ♡';setTimeout(()=>document.getElementById('reviewSaved').textContent='',2500)};
document.getElementById('shopGrid').addEventListener('click',e=>{let b=e.target.closest('[data-buy]');if(b)buy(b.dataset.buy)});document.getElementById('homeRewards').addEventListener('click',()=>nav('rewards'));
document.getElementById('saveSettings').onclick=()=>{data.name=document.getElementById('nameInput').value.trim()||'lovely';let start=document.getElementById('startDay').value;data.challengeStart=start||data.challengeStart;data.settings.streak=document.getElementById('streakToggle').checked;save();render();document.getElementById('settingsSaved').textContent='Your sanctuary is updated ♡';setTimeout(()=>document.getElementById('settingsSaved').textContent='',2500)};document.getElementById('resetData').onclick=()=>{if(confirm('Start fresh? This permanently clears your quests, pearls, reflections and settings saved in this browser.')){data=blank();save();render();nav('home');toast('A fresh page, whenever you are ready ♡')}};
document.getElementById('modalClose').onclick=closeModal;document.getElementById('modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()};document.getElementById('modalBackdrop').onkeydown=e=>{if(e.key==='Escape')closeModal()};document.addEventListener('click',e=>{let d=e.target.closest('[data-challenge]');if(d&&d.tagName!=='BUTTON')return});document.getElementById('challengeGrid').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){let b=e.target.closest('[data-challenge]');if(b){e.preventDefault();b.click()}}});
render();
})();
